import type { IncomingMessage, OutgoingMessage, ListSessionsMessage, SessionListMessage } from './messages.js';

describe('message types', () => {
  it('defines the list_sessions incoming message', () => {
    const msg: ListSessionsMessage = { type: 'list_sessions' };
    const incoming: IncomingMessage = msg;
    expect(incoming.type).toBe('list_sessions');
  });

  it('defines the session_list outgoing message', () => {
    const msg: SessionListMessage = { type: 'session_list', sessions: [] };
    const outgoing: OutgoingMessage = msg;
    expect(outgoing.type).toBe('session_list');
  });
});

