function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const data: ListSessionsMessage = {type: 'list_sessions'};

  if (message.limit !== undefined) {
    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0) {
      return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
    }
    data.limit = message.limit;
  }

  if (message.before !== undefined) {
    if (typeof message.before !== 'object' || message.before === null) {
      return {valid: false, error: 'list_sessions before must be an object'};
    }
    const before = message.before as Record<string, unknown>;
    if (typeof before.sessionId !== 'string' || before.sessionId.length < 1 || before.sessionId.length > 128) {
      return {valid: false, error: 'list_sessions before.sessionId must be 1-128 chars'};
    }
    if (typeof before.updatedAt !== 'string' && typeof before.updatedAt !== 'number') {
      return {valid: false, error: 'list_sessions before.updatedAt must be a string or number'};
    }
    if (typeof before.updatedAt === 'number' && !Number.isFinite(before.updatedAt)) {
      return {valid: false, error: 'list_sessions before.updatedAt must be a finite number'};
    }
    if (typeof before.updatedAt === 'string' && isNaN(Date.parse(before.updatedAt))) {
      return {valid: false, error: 'list_sessions before.updatedAt must be a valid date string'};
    }
    data.before = {
      sessionId: before.sessionId,
      updatedAt: before.updatedAt as string | number,
    };
  }

  return {valid: true, data};
}

